fn optional_uniform_insets(value: Option<f64>) -> Option<sui_crate::Insets> {
    value.map(|value| {
        let value = (value as f32).max(0.0);
        sui_crate::Insets {
            left: value,
            top: value,
            right: value,
            bottom: value,
        }
    })
}

